{
  "requirements": [
    {
      "id": "F-01",
      "text": "The library management system shall ensure that only authenticated members can borrow or return books.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-01"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The library management system shall log all borrowing transactions for auditability.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-02"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-03",
      "text": "The library management system shall enforce data encryption for all member personal information stored.",
      "quality_axes": ["Trustworthiness|Responsibility"],
      "derived_from": ["TRU-03", "RES-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-04",
      "text": "The library management system shall implement role-based access control for librarians and members.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-05",
      "text": "The library management system shall provide a mechanism to report and manage overdue books securely.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-06",
      "text": "The library management system shall allow members to update their personal information securely.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The library management system shall require strong password policies for member accounts.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-07"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-08",
      "text": "The library management system shall enable searching for books with a response time of under 2 seconds for 95% of queries.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-01"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-09",
      "text": "The library management system shall allow up to 10 simultaneous book borrow operations per member.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-02"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-10",
      "text": "The library management system shall track book availability and update the status in real-time.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-11",
      "text": "The library management system shall process book returns within 1 second to maintain high throughput.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-12",
      "text": "The library management system shall send overdue notifications to members within 24 hours of the due date.",
      "quality_axes": ["Efficiency|Responsibility"],
      "derived_from": ["EFF-05", "GRN-03", "SAF-02"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-13",
      "text": "The library management system shall maintain an uptime of 99.5% to ensure consistent availability.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-07"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-14",
      "text": "The library management system shall minimize energy consumption by using energy-efficient servers.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-15",
      "text": "The library management system shall provide an energy usage report for library operations at least quarterly.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-16",
      "text": "The library management system shall allow members to check the carbon footprint of each book.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-04"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-17",
      "text": "The library management system shall implement a recycling program for damaged books.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-18",
      "text": "The library management system shall track the total energy savings achieved through digital operations.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-06"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-19",
      "text": "The library management system shall prioritize the acquisition of e-books to reduce physical resource consumption.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-07"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-20",
      "text": "The library management system shall provide an accessible interface for all users, including those with disabilities.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-21",
      "text": "The library management system shall log all user actions related to book borrowing and returning for accountability.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-22",
      "text": "The library management system shall adhere to library borrowing policies by enforcing a maximum of 5 books per member.",
      "quality_axes": ["Responsibility|Safety"],
      "derived_from": ["RES-04", "SAF-01"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-23",
      "text": "The library management system shall implement a user authentication process to ensure only registered members can access borrowing features.",
      "quality_axes": ["Safety|Trustworthiness"],
      "derived_from": ["SAF-06", "TRU-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-24",
      "text": "The library management system shall implement a backup mechanism to recover all transaction data in case of a failure.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-04"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-25",
      "text": "The library management system shall allow librarians to revoke borrowing privileges for members with outstanding overdue books.",
      "quality_axes": ["Safety|Responsibility"],
      "derived_from": ["SAF-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-26",
      "text": "The library management system shall maintain real-time inventory status of all books to prevent double borrowing.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-03"],
      "kaos_level": "operational",
      "parent": null
    }
  ],
  "conflict_resolutions": [
